    "Click to add points. Click the green point to close. Drag points to move them. Right-click a point to delete it.": "Klik om punten toe te voegen. Klik op het groene punt om te sluiten. Sleep punten om ze te verplaatsen. Klik met de rechtermuisknop op een punt om het te verwijderen.",
