    "Connect": "Verbinden",
    "Connect once here to use your fixed, variable or dynamic energy contract across SmartHomeShop Energy. The integration keeps working locally without an account.": "Maak hier één keer verbinding om je vaste, variabele of dynamische energiecontract in heel SmartHomeShop Energy te gebruiken. De integratie blijft ook zonder account lokaal werken.",
