    "Connect or select a P1 meter first to configure smart energy automations.": "Verbind of selecteer eerst een P1-meter om Smart Energy-automatiseringen in te stellen.",
    "Connect the selected P1 meter to the native HA Energy Dashboard or import compatible HA source mappings into Smart Energy.": "Koppel de geselecteerde P1-meter aan het eigen energiedashboard van HA of importeer compatibele HA-bronkoppelingen in Smart Energy.",
