    "SmartHomeShop Energy is pinned to a specific contract. Pick a location above to follow its active contract instead.": "SmartHomeShop Energy is vastgezet op een specifiek contract. Kies hierboven een locatie om in plaats daarvan het actieve contract van die locatie te volgen.",
