    "Use solar surplus for a device": "Gebruik zonneoverschot voor een apparaat",
    "Use the lowest value accepted by the inverter. A small non-zero limit is safer for many models.": "Gebruik de laagste waarde die de omvormer accepteert. Een kleine limiet boven nul is voor veel modellen veiliger.",
    "Used for the smart-savings estimate and the fuse guard below.": "Gebruikt voor de Smart Savings-schatting en de zekeringbeveiliging hieronder.",
    "Used to stop charging at the target and to protect the reserve in battery arbitrage.": "Gebruikt om te stoppen met laden bij het doel en om de reserve te beschermen bij batterijarbitrage.",
    "Used when no capacity entity is selected or when that entity is temporarily unavailable.": "Gebruikt wanneer geen capaciteitsentiteit is geselecteerd of wanneer die entiteit tijdelijk niet beschikbaar is.",
    "Used when no load forecast is selected.": "Gebruikt wanneer geen verbruiksvoorspelling is geselecteerd.",
    "Usually 100 for a percentage entity, or the inverter maximum for a watt-based entity.": "Meestal 100 bij een percentage-entiteit, of het maximum van de omvormer bij een entiteit in watt.",
    "Visualization only": "Alleen visualisatie",
    "Wait for the LD2460 installation settings before pushing zones": "Wacht op de installatie-instellingen van de LD2460 voordat je zones pusht",
    "Waiting for capacity": "Wachten op capaciteit",
    "Waiting for confirmed price data": "Wachten op bevestigde prijsgegevens",
    "Waiting for the first complete plan.": "Wachten op het eerste complete plan.",
    "Walk to each edge of the area the sensor can reliably detect. Stand still and select Mark. Your position is averaged over 5 seconds.": "Loop naar elke rand van het gebied dat de sensor betrouwbaar kan detecteren. Sta stil en selecteer Mark. Je positie wordt over 5 seconden gemiddeld.",
    "Wall mounted": "Wandmontage",
