    "Check the mounting mode and installation data of the linked radars first.": "Controleer eerst de montagemodus en installatiegegevens van de gekoppelde radars.",
    "This room has no zones. Sending clears the zones on its radars.": "Deze kamer heeft geen zones. Verzenden wist de zones op de radars.",
