    "Auto": "Automatisch",
    "No live target positions right now.": "Derzeit gibt es keine Live-Zielpositionen.",
    "Live radar data is temporarily unavailable. Old positions have been hidden until the device responds again.": "Live-Radardaten sind vorübergehend nicht verfügbar. Alte Positionen bleiben ausgeblendet, bis das Gerät wieder antwortet.",
    "Live device data is temporarily unavailable.": "Live-Gerätedaten sind vorübergehend nicht verfügbar.",
    "The device page will retry automatically. You can also try again now.": "Die Geräteseite versucht es automatisch erneut. Du kannst es auch jetzt erneut versuchen.",
    "{count} live positions": "{count} Live-Positionen",
    "Live target position details": "Details der Live-Zielpositionen",
    "Target {index}: position unavailable.": "Ziel {index}: Position nicht verfügbar.",
    "Target {index}: X {x} m, Y {y} m, {height}.": "Ziel {index}: X {x} m, Y {y} m, {height}.",
    "height unknown": "Höhe unbekannt",
    "height {height} m": "Höhe {height} m",
    "Live 2D radar positions": "Live-2D-Radarpositionen",
    "Live 3D radar positions": "Live-3D-Radarpositionen",
    "Multiple radar views are fused for position, while the exact person count remains conservative.": "Mehrere Radaransichten werden für die Position zusammengeführt; die genaue Personenzahl bleibt vorsichtshalber unbekannt.",
    "One physical radar can only be linked to one room. Unlink it from the other room and try again.": "Ein physischer Radar kann nur mit einem Raum verknüpft sein. Löse ihn vom anderen Raum und versuche es erneut.",
    "Some saved room data could not be loaded safely. The original data was kept for recovery.": "Einige gespeicherte Raumdaten konnten nicht sicher geladen werden. Die ursprünglichen Daten wurden zur Wiederherstellung aufbewahrt.",
    "Mirror": "Spiegel",
    "MIRRORS": "SPIEGEL",
    "Add Mirror": "Spiegel hinzufügen",
    "Edit Mirror": "Spiegel bearbeiten",
    "Reflection guard": "Reflexionsschutz",
    "Reflection protection": "Reflexionsschutz",
    "Reflection protection enabled": "Reflexionsschutz aktiviert",
    "Visual only": "Nur visuell",
    "No mirrors added yet.": "Noch keine Spiegel hinzugefügt.",
    "Place the mirror on its real wall. Optional reflection protection filters predicted ghost targets behind it.": "Platziere den Spiegel an seiner tatsächlichen Wand. Der optionale Reflexionsschutz filtert vorhergesagte Geisterziele dahinter.",
    "Place the mirror on the wall where it is physically installed.": "Platziere den Spiegel an der Wand, an der er tatsächlich montiert ist.",
    "Filter ghost targets predicted behind this mirror and send the area to each linked radar as an exclusion polygon.": "Filtert vorhergesagte Geisterziele hinter diesem Spiegel und sendet den Bereich als Ausschlusspolygon an jedes verknüpfte Radar.",
    "Protection depth (cm)": "Schutztiefe (cm)",
    "The dashed preview follows the radar rays beyond the mirror. Increase the depth only when ghost targets appear farther behind it.": "Die gestrichelte Vorschau folgt den Radarstrahlen hinter den Spiegel. Erhöhe die Tiefe nur, wenn Geisterziele weiter dahinter erscheinen.",
    "Each protected mirror uses one of the radar's two exclusion slots. Raw diagnostic target entities remain unchanged; the Floorplan Designer, the UltimateSensor room view and firmware people counting ignore the protected area.": "Jeder geschützte Spiegel nutzt einen der zwei Ausschlussplätze des Radars. Rohe Diagnose-Zielentitäten bleiben unverändert; der Grundriss-Designer, die UltimateSensor-Raumansicht und die Personenzählung der Firmware ignorieren den geschützten Bereich.",
    "{used}/2 radar exclusion slots used.": "{used}/2 Radar-Ausschlussplätze verwendet.",
    "Disable protection for a mirror or remove a manual exclusion before pushing.": "Deaktiviere den Schutz eines Spiegels oder entferne einen manuellen Ausschluss vor dem Übertragen.",
    "Link a radar placement to preview and use reflection protection. The mirror can still be saved visually.": "Verknüpfe eine Radarplatzierung, um den Reflexionsschutz anzuzeigen und zu nutzen. Der Spiegel kann trotzdem visuell gespeichert werden.",
    "Reflection protection needs {total} exclusion slots for {sensor}, but the radar supports 2. Disable protection for a mirror or remove a manual exclusion zone.": "Der Reflexionsschutz benötigt {total} Ausschlussplätze für {sensor}, das Radar unterstützt aber nur 2. Deaktiviere den Schutz eines Spiegels oder entferne eine manuelle Ausschlusszone.",
