    "The LiDAR scan does not contain a complete room boundary. Scan every wall and export it as Apple RoomPlan JSON.": "Der LiDAR-Scan enthält keine vollständige Raumbegrenzung. Scanne alle Wände und exportiere ihn als Apple-RoomPlan-JSON.",
    "That file is neither a SmartHomeShop room backup nor an Apple RoomPlan LiDAR scan.": "Diese Datei ist weder eine SmartHomeShop-Raumsicherung noch ein Apple-RoomPlan-LiDAR-Scan.",
    "Import LiDAR scan": "LiDAR-Scan importieren",
    "Apple RoomPlan scan detected. Review the converted room before adding it; the original scan and existing rooms are not changed.": "Apple-RoomPlan-Scan erkannt. Prüfe den umgewandelten Raum vor dem Hinzufügen; der ursprüngliche Scan und bestehende Räume bleiben unverändert.",
    "Apple RoomPlan (LiDAR scan)": "Apple RoomPlan (LiDAR-Scan)",
