    "One or more scan edges did not meet exactly. The closest wall endpoints were joined; review the room shape.": "Eine oder mehrere Scankanten trafen nicht genau aufeinander. Die nächstgelegenen Wandenden wurden verbunden; prüfe die Raumform.",
