    "Dynamic price data is unavailable. Check the SmartHomeShop.io API key to enable home battery planning.": "Dynamische Preisdaten sind nicht verfügbar. Prüfe den SmartHomeShop.io-API-Schlüssel, um die Planung deines Heimspeichers zu ermöglichen.",
