    "Dynamic prices, solar, battery, EV and inverter automations are configured once for the whole home under Energy settings.": "Automationen für dynamische Preise, PV, Batterie, E-Auto und Wechselrichter konfigurierst du einmal für das ganze Haus unter Energieeinstellungen.",
