    "Smart savings": "Smart Savings",
    "SmartHomeShop chooses the correct cumulative sensors and keeps other Energy Dashboard sources.": "SmartHomeShop wählt die richtigen kumulativen Sensoren und behält andere Quellen im Energie-Dashboard bei.",
    "SmartHomeShop device": "SmartHomeShop-Gerät",
    "SmartHomeShop Energy is pinned to a specific contract. Pick a location above to follow its active contract instead.": "SmartHomeShop Energy ist an einen bestimmten Vertrag gebunden. Wähle oben einen Standort aus, um stattdessen dessen aktivem Vertrag zu folgen.",
    "SmartHomeShop not linked": "SmartHomeShop nicht verknüpft",
    "SmartHomeShop setup complete. The new energy sensors are ready.": "SmartHomeShop-Einrichtung abgeschlossen. Die neuen Energiesensoren sind bereit.",
