    "Use firmware mounting": "Montage aus der Firmware verwenden",
    "Use measured area": "Gemessenen Bereich verwenden",
    "Use solar surplus for a device": "PV-Überschuss für ein Gerät nutzen",
    "Use the lowest value accepted by the inverter. A small non-zero limit is safer for many models.": "Verwende den niedrigsten Wert, den der Wechselrichter akzeptiert. Ein kleines Limit über null ist für viele Modelle sicherer.",
    "Used for the smart-savings estimate and the fuse guard below.": "Wird für die Smart-Savings-Schätzung und den Sicherungsschutz unten verwendet.",
    "Used to stop charging at the target and to protect the reserve in battery arbitrage.": "Wird verwendet, um das Laden am Ziel zu stoppen und die Reserve bei der Batteriearbitrage zu schützen.",
    "Used when no capacity entity is selected or when that entity is temporarily unavailable.": "Wird verwendet, wenn keine Kapazitätsentität ausgewählt wurde oder wenn diese vorübergehend nicht verfügbar ist.",
    "Used when no load forecast is selected.": "Wird verwendet, wenn keine Verbrauchsprognose ausgewählt ist.",
    "Usually 100 for a percentage entity, or the inverter maximum for a watt-based entity.": "Meist 100 bei einer Prozent-Entität oder das Maximum des Wechselrichters bei einer Entität in Watt.",
    "Visualization only": "Nur Visualisierung",
    "Wait for the LD2460 installation settings before pushing zones": "Warte auf die LD2460-Installationseinstellungen, bevor du Zonen überträgst",
    "Waiting for capacity": "Warten auf Kapazität",
    "Waiting for confirmed price data": "Warten auf bestätigte Preisdaten",
    "Waiting for the first complete plan.": "Warten auf den ersten vollständigen Plan.",
    "Walk to each edge of the area the sensor can reliably detect. Stand still and select Mark. Your position is averaged over 5 seconds.": "Gehe zu jedem Rand des Bereichs, den der Sensor zuverlässig erkennen kann. Bleib stehen und wähle Mark. Deine Position wird über 5 Sekunden gemittelt.",
    "Wall mounted": "Wandmontage",
    "Walls": "Wände",
    "Water": "Wasser",
    "Water has been flowing non-stop - possible leak or running tap.": "Wasser fließt ununterbrochen: mögliches Leck oder laufender Wasserhahn.",
    "Water is being used during the night.": "Nachts wird Wasser verbraucht.",
    "Water leak sensor wet": "Wasserlecksensor nass",
    "water monitoring, leak detection and usage insights": "Wasserüberwachung, Leckerkennung und Verbrauchseinblicke",
