    "Water today": "Wasser heute",
    "Water total": "Wasser insgesamt",
    "Welcome! Connect your SmartHomeShop account": "Willkommen! Verbinde dein SmartHomeShop-Konto",
    "What smart energy earned": "Was Smart Energy eingebracht hat",
    "When the feed-in price goes negative (you would pay to export), switch on a diversion load to self-consume instead. Off again when feed-in is positive.": "Wenn der Einspeisepreis negativ wird und du für die Einspeisung zahlen würdest, schalte stattdessen einen zusätzlichen Verbraucher für den Eigenverbrauch ein. Schalte ihn wieder aus, sobald der Einspeisepreis positiv ist.",
    "Width (cm)": "Breite (cm)",
    "Window type": "Fenstertyp",
    "Writable inverter limit or safe enable control": "Beschreibbares Wechselrichterlimit oder sichere Einschaltfunktion",
    "You are measuring the sensor, not the room": "Du misst den Sensor, nicht den Raum",
    "You have unsaved changes. Discard them?": "Du hast nicht gespeicherte Änderungen. Verwerfen?",
    "You need an administrator account to create automations.": "Du brauchst ein Administratorkonto, um Automationen zu erstellen.",
    "Your API key works, but the selected location has no active energy contract, so there are no prices to plan against. Add or activate a contract in your SmartHomeShop account, or pick another location in Settings.": "Dein API-Schlüssel funktioniert, aber der ausgewählte Standort hat keinen aktiven Energievertrag, daher gibt es keine Preise für die Planung. Füge in deinem SmartHomeShop-Konto einen Vertrag hinzu oder aktiviere ihn, oder wähle in den Einstellungen einen anderen Standort.",
    "Your P1 meter covers the grid. If you have solar panels or a home battery, connect their sensors so the Energy tab shows real surplus and state of charge. You can always do this later from Settings.": "Dein P1-Zähler deckt das Netz ab. Wenn du PV-Module oder einen Heimspeicher hast, verbinde deren Sensoren, damit der Tab Energie den echten Überschuss und den Ladezustand zeigt. Das kannst du auch später jederzeit in den Einstellungen tun.",
    "Your P1 meter only sees the grid. Connect your solar and battery entities (you already have them in Home Assistant) so we can see real solar surplus and your battery's charge level.": "Dein P1-Zähler sieht nur das Netz. Verbinde deine PV- und Batterie-Entitäten (die hast du bereits in Home Assistant), damit wir den echten PV-Überschuss und den Ladezustand deiner Batterie sehen können.",
    "Your polygon zone is drawn! Choose what type this zone should be.": "Deine Polygonzone ist gezeichnet! Wähle, welcher Typ diese Zone sein soll.",
    "Your return value is higher than today's import cost.": "Deine Einspeisevergütung ist höher als die heutigen Bezugskosten.",
    "Your sensors are detected automatically.": "Deine Sensoren werden automatisch erkannt.",
