    "Existing device data is still shown. Check the connection and try again.": "Les données existantes des appareils restent affichées. Vérifiez la connexion et réessayez.",
    "Check the Home Assistant connection and try again.": "Vérifiez la connexion à Home Assistant et réessayez.",
    "Device filters": "Filtres des appareils",
