    "Showing {shown} of {total} devices": "{shown} appareils affichés sur {total}",
    "Showing online devices first. {count} offline devices are hidden; choose All to view them.": "Les appareils en ligne sont affichés en premier. {count} appareils hors ligne sont masqués ; choisissez Tous pour les afficher.",
    "No devices match these filters": "Aucun appareil ne correspond à ces filtres",
    "Try another search or show all devices.": "Essayez une autre recherche ou affichez tous les appareils.",
    "Clear search and filters": "Effacer la recherche et les filtres",
