    "Rooms": "Pièces",
    "Export": "Exporter",
    "Import room backup or LiDAR scan": "Importer une sauvegarde de pièce ou un scan LiDAR",
    "Choose a SmartHomeShop room backup or Apple RoomPlan scan (.json).": "Choisissez une sauvegarde de pièce SmartHomeShop ou un scan Apple RoomPlan (.json).",
    "LiDAR room": "Pièce LiDAR",
    "The LiDAR scan does not contain a complete room boundary. Scan every wall and export it as Apple RoomPlan JSON.": "Le scan LiDAR ne contient pas un contour complet de la pièce. Scannez tous les murs et exportez-le au format JSON Apple RoomPlan.",
    "That file is neither a SmartHomeShop room backup nor an Apple RoomPlan LiDAR scan.": "Ce fichier n'est ni une sauvegarde de pièce SmartHomeShop ni un scan LiDAR Apple RoomPlan.",
    "Import LiDAR scan": "Importer un scan LiDAR",
    "Apple RoomPlan scan detected. Review the converted room before adding it; the original scan and existing rooms are not changed.": "Scan Apple RoomPlan détecté. Vérifiez la pièce convertie avant de l'ajouter ; le scan d'origine et les pièces existantes ne sont pas modifiés.",
    "Apple RoomPlan (LiDAR scan)": "Apple RoomPlan (scan LiDAR)",
    "SmartHomeShop room backup": "Sauvegarde de pièce SmartHomeShop",
    "One room detected with measurements in metres.": "Une pièce détectée avec des mesures en mètres.",
    "{count} rooms detected with measurements in metres.": "{count} pièces détectées avec des mesures en mètres.",
    "Complete room layout and settings.": "Agencement et réglages complets de la pièce.",
    "Room from scan": "Pièce issue du scan",
    "Imported room contents": "Contenu de la pièce importée",
    "RoomPlan measurements are converted from metres to millimetres. Check the walls, doors, windows and furniture after import because LiDAR scans can contain small gaps.": "Les mesures RoomPlan sont converties de mètres en millimètres. Vérifiez les murs, portes, fenêtres et meubles après l'importation, car les scans LiDAR peuvent contenir de petits écarts.",
    "One or more scan edges did not meet exactly. The closest wall endpoints were joined; review the room shape.": "Un ou plusieurs bords du scan ne se rejoignaient pas exactement. Les extrémités de mur les plus proches ont été reliées ; vérifiez la forme de la pièce.",
    "A scanned door or window was too far from a wall and was skipped.": "Une porte ou une fenêtre scannée était trop éloignée d'un mur et a été ignorée.",
    "Some scanned objects do not match the furniture library and were skipped.": "Certains objets scannés ne correspondent pas à la bibliothèque de meubles et ont été ignorés.",
    "Import room from file": "Importer une pièce depuis un fichier",
    "Export selected room": "Exporter la pièce sélectionnée",
    "Choose a SmartHomeShop room backup (.json).": "Choisissez une sauvegarde de pièce SmartHomeShop (.json).",
    "That file is too large. Choose a room backup smaller than 2 MB.": "Ce fichier est trop volumineux. Choisissez une sauvegarde de moins de 2 Mo.",
    "That is not a valid SmartHomeShop room backup.": "Ce fichier n'est pas une sauvegarde de pièce SmartHomeShop valide.",
    "This backup was created by a newer SmartHomeShop version. Update the integration before importing it.": "Cette sauvegarde a été créée avec une version plus récente de SmartHomeShop. Mettez l'intégration à jour avant de l'importer.",
    "{name} (imported)": "{name} (importée)",
    "Exported {name}.": "{name} a été exportée.",
