    "Calibration saved.": "Étalonnage enregistré.",
    "This room changed elsewhere. Reload it before measuring again.": "Cette pièce a été modifiée ailleurs. Rechargez-la avant de recommencer la mesure.",
    "Push finished with warnings": "Envoi terminé avec des avertissements",
