    "Notify when fine dust rises above a healthy level.": "Prévient quand les particules fines dépassent un niveau sain.",
    "Notify when it gets cold in the room.": "Prévient quand il fait froid dans la pièce.",
    "Notify when nobody has been present for a while.": "Prévient quand personne n'est présent depuis un moment.",
    "Notify when power draw stays above a limit.": "Prévient quand la puissance consommée reste au-dessus d'une limite.",
    "Notify when power stays above a limit between midnight and 06:00.": "Prévient quand la puissance reste au-dessus d'une limite entre minuit et 06:00.",
    "Notify when smart leak detection flags unusual usage.": "Prévient quand la détection intelligente des fuites signale une consommation inhabituelle.",
    "Notify when solar export stays above a chosen limit.": "Prévient quand l'injection solaire reste au-dessus d'une limite choisie.",
    "Notify when the air gets very dry.": "Prévient quand l'air devient très sec.",
    "Notify when the difference between the highest and lowest phase current is too large.": "Prévient quand l'écart entre le courant de phase le plus élevé et le plus bas est trop grand.",
    "Notify when the temperature climbs too high.": "Prévient quand la température monte trop haut.",
    "Notify when the water usage today passes a limit.": "Prévient quand la consommation d'eau du jour dépasse une limite.",
    "Notify when today's electricity use passes a limit.": "Prévient quand la consommation d'électricité du jour dépasse une limite.",
    "Notify when water flows non-stop (running tap or leak).": "Prévient quand l'eau coule sans arrêt (robinet ouvert ou fuite).",
    "Notify when water is used during the night.": "Prévient quand de l'eau est utilisée pendant la nuit.",
    "Off after": "Arrêt après",
    "Off by default. With this disabled, Home Assistant only exposes advice sensors.": "Désactivé par défaut. Dans ce cas, Home Assistant expose uniquement des capteurs de conseil.",
    "Office Chair": "Chaise de bureau",
    "Offline": "Hors ligne",
    "On after": "Marche après",
    "On when export exceeds this. Its own draw creates the off-hysteresis.": "S'active quand l'injection dépasse cette valeur. Sa propre consommation crée l'hystérésis d'arrêt.",
    "One connection unlocks live dynamic prices, cheapest-hours planning, deadline schedules and battery control. Create a free API key in your account and paste it here.": "Une seule connexion donne accès aux prix dynamiques en direct, à la planification des heures les moins chères, aux plannings à échéance et au contrôle de la batterie. Créez une clé API gratuite dans votre compte et collez-la ici.",
    "One-click automations for this device - pick the ones you want and choose where the notification goes. Each becomes a normal Home Assistant automation you can fine-tune later in the automation editor.": "Automatisations en un clic pour cet appareil. Choisissez celles que vous voulez et où envoyer la notification. Chacune devient une automatisation Home Assistant normale, que vous pourrez affiner plus tard dans l'éditeur d'automatisations.",
    "Online": "En ligne",
    "Only grid power is connected. Add your solar and battery entities to see production, storage and state of charge.": "Seule la puissance du réseau est connectée. Ajoutez vos entités solaires et de batterie pour voir la production, le stockage et l'état de charge.",
    "Only the name changes. Your layout, sensors and zones stay in place.": "Seul le nom change. Votre disposition, vos capteurs et vos zones restent en place.",
    "Only this sensor counts crossings on this line, so people are not counted twice.": "Seul ce capteur compte les passages sur cette ligne, afin que les personnes ne soient pas comptées deux fois.",
