    "Preferred: select a writable inverter active-power/output-limit number. Only use the switch fallback with the inverter manufacturer's safe enable control or a dedicated helper that calls that control. Never switch the inverter's AC supply with a smart plug, relay or contactor. The fallback can briefly export during every test start.": "Préféré : sélectionnez un nombre modifiable pour la puissance active ou la limite de sortie de l'onduleur. N'utilisez le repli par interrupteur qu'avec la commande d'activation sécurisée du fabricant de l'onduleur ou une entrée dédiée qui appelle cette commande. Ne commutez jamais l'alimentation en courant alternatif de l'onduleur avec une prise connectée, un relais ou un contacteur. Le repli peut injecter brièvement à chaque démarrage de test.",
