    "Start EV charging at the beginning of the cheapest block and stop at the end.": "Démarrez la recharge du VE au début du bloc le moins cher et arrêtez-la à la fin.",
    "Start live measurement": "Démarrer la mesure en direct",
    "State-of-charge sensor": "Capteur d'état de charge",
    "Steer devices around prices and solar production. Loads can run in cheap or surplus hours, while inverter output can be reduced safely to avoid unwanted export. Each setup creates a normal, editable Home Assistant automation with restart recovery and fail-safe behaviour.": "Pilotez vos appareils selon les prix et la production solaire. Les charges peuvent fonctionner aux heures bon marché ou en cas de surplus, tandis que la sortie de l'onduleur peut être réduite en toute sécurité pour éviter une injection indésirable. Chaque configuration crée une automatisation Home Assistant normale et modifiable, avec reprise après redémarrage et comportement sûr en cas de panne.",
    "Surplus needed": "Excédent nécessaire",
    "Switch a deferrable load (boiler, pump, ventilation) on during the cheapest contiguous block of the day and off when it ends.": "Allumez une charge reportable (chauffe-eau, pompe, ventilation) pendant le bloc continu le moins cher de la journée et éteignez-la à la fin du bloc.",
    "Switch a load off when the price level hits its daily peak and back on when it drops. Trims the most expensive hours.": "Éteignez une charge lorsque le niveau de prix atteint son pic quotidien et rallumez-la quand il baisse. Réduit la consommation aux heures les plus chères.",
    "Switch a load on when the house exports more than it needs, and off when you would start importing - with hysteresis + dwell so it does not flap.": "Allumez une charge lorsque la maison injecte plus qu'elle n'en a besoin, et éteignez-la quand vous commenceriez à consommer du réseau, avec hystérésis et temporisation pour éviter les basculements répétés.",
    "Switch off after": "Arrêt après",
    "Sync now": "Synchroniser maintenant",
