    "Link an available Home Assistant radar in Floor plan to use these controls.": "Associez un radar Home Assistant disponible dans le plan pour utiliser ces commandes.",
    "Coverage and calibration": "Couverture et étalonnage",
    "points": "points",
    "Save your new measurements or discard them to switch rooms.": "Enregistrez ou ignorez vos nouvelles mesures pour changer de pièce.",
    "This radar must provide usable position data to measure coverage.": "Ce radar doit fournir des positions exploitables pour mesurer la couverture.",
