    "Check the mounting mode and installation data of the linked radars first.": "Vérifiez d'abord le mode de montage et les données d'installation des radars associés.",
    "This room has no zones. Sending clears the zones on its radars.": "Cette pièce n'a aucune zone. L'envoi efface les zones de ses radars.",
    "Send this room's saved zones to its linked radars.": "Envoyez les zones enregistrées de cette pièce aux radars associés.",
    "Sending...": "Envoi...",
    "Send to radars": "Envoyer aux radars",
    "Reload room": "Recharger la pièce",
    "Combine multiple CeilSense and UltimateSensor devices into reliable values for this room.": "Combinez plusieurs appareils CeilSense et UltimateSensor pour obtenir des valeurs fiables pour cette pièce.",
    "Combined presence": "Présence combinée",
    "Occupied": "Occupée",
    "Clear": "Libre",
    "Waiting before clearing": "Attente avant de signaler la pièce libre",
    "Unknown, waiting for fresh sensor data": "Inconnu, en attente de données récentes",
    "Degraded": "Dégradé",
    "Presence sources": "Sources de présence",
    "Any fresh positive sensor marks the room occupied. The room only clears when every selected sensor reports fresh and clear data.": "Un capteur positif récent indique que la pièce est occupée. Elle n'est déclarée libre que lorsque tous les capteurs sélectionnés transmettent des données récentes et libres.",
    "Capabilities not reported": "Capacités non signalées",
    "No fresh update": "Aucune mise à jour récente",
    "{seconds}s ago": "il y a {seconds}s",
    "Use {name} for combined presence": "Utiliser {name} pour la présence combinée",
    "Unknown": "Inconnu",
    "Link at least one supported sensor to create room-wide results.": "Associez au moins un capteur pris en charge pour créer des résultats pour toute la pièce.",
    "Data freshness (seconds)": "Fraîcheur des données (secondes)",
    "Clear delay (seconds)": "Délai avant libération (secondes)",
    "Any available positive sensor marks the room occupied. The room only clears when every selected sensor is available and clear.": "Tout capteur disponible et positif marque la pièce comme occupée. La pièce n'est déclarée libre que lorsque chaque capteur sélectionné est disponible et libre.",
    "Average available readings, choose one primary sensor, or keep the individual sensor entities separate.": "Calculez la moyenne des mesures disponibles, choisissez un capteur principal ou conservez les entités de capteur séparées.",
    "Average available readings": "Moyenne des mesures disponibles",
    "Room climate": "Climat de la pièce",
    "Average fresh readings, choose one primary sensor, or keep the individual sensor entities separate.": "Faites la moyenne des mesures récentes, choisissez un capteur principal ou conservez les entités séparées.",
    "Temperature": "Température",
    "Average fresh readings": "Moyenne des mesures récentes",
    "Primary sensor": "Capteur principal",
    "Keep separate": "Conserver séparément",
    "Primary sensor for {metric}": "Capteur principal pour {metric}",
    "Select a sensor": "Sélectionner un capteur",
    "Large-room tracking": "Suivi des grandes pièces",
    "Experimental overlapping-track fusion": "Fusion expérimentale des trajectoires superposées",
    "Keep this off unless every positioning radar is calibrated in the same room coordinate system. Without calibration, each source track remains visible but no joint people count is claimed.": "Laissez cette option désactivée sauf si chaque radar de positionnement est calibré dans le même repère de pièce. Sans calibrage, chaque trajectoire source reste visible, mais aucun comptage commun n'est annoncé.",
    "Duplicate track distance (mm)": "Distance des trajectoires en double (mm)",
    "Duplicate distance changed. Repeat the neighbouring overlap alignment before fusion can resume.": "La distance des trajectoires en double a changé. Répétez l'alignement du chevauchement voisin avant de réactiver la fusion.",
    "Create one continuous room track when a person walks from one radar range into another. Local track IDs always remain tied to their source sensor.": "Crée une trajectoire continue dans la pièce lorsqu'une personne passe d'une portée radar à une autre. Les identifiants locaux restent liés à leur capteur source.",
    "Alignment verified. Room-wide handover is ready.": "Alignement vérifié. Le relais dans toute la pièce est prêt.",
    "Link at least two positioning radars to enable room-wide handover.": "Associez au moins deux radars de positionnement pour activer le relais dans toute la pièce.",
    "A sensor placement changed. Repeat the alignment test before fusion can resume.": "Le placement d'un capteur a changé. Répétez le test d'alignement avant de reprendre la fusion.",
    "Walk test required before overlapping tracks can be merged.": "Un test de marche est requis avant de fusionner les trajectoires superposées.",
    "Three-position alignment test": "Test d'alignement à trois positions",
    "Neighbouring overlap alignment": "Alignement des chevauchements voisins",
    "Keep one person visible to two neighbouring radars and capture three well-separated positions. Then repeat in the next overlap until all radars are connected. The test never rewrites radar coordinates.": "Gardez une personne visible par deux radars voisins et capturez trois positions bien espacées. Répétez ensuite dans le chevauchement suivant jusqu'à ce que tous les radars soient reliés. Le test ne réécrit jamais les coordonnées radar.",
    "Capture overlap position": "Capturer la position de chevauchement",
    "This radar is already placed in this room. Choose another device.": "Ce radar est déjà placé dans cette pièce. Choisissez un autre appareil.",
    "This radar is already linked to {room}. Unlink it there before using it in this room.": "Ce radar est déjà associé à {room}. Dissociez-le de cette pièce avant de l'utiliser ici.",
    "Keep one person visible to every positioning radar. Capture three well-separated positions. The test checks the saved sensor positions and rotations; it does not rewrite radar coordinates.": "Gardez une personne visible par chaque radar. Capturez trois positions bien séparées. Le test vérifie les positions et rotations enregistrées sans réécrire les coordonnées radar.",
    "Capture position {count}/3": "Capturer la position {count}/3",
    "Keep exactly one person visible to at least two neighbouring positioning sensors, then capture again.": "Gardez exactement une personne visible par au moins deux capteurs de position voisins, puis capturez à nouveau.",
    "Captured {count}/3 positions for this sensor pair. Walk to a clearly different part of their overlap.": "{count}/3 positions capturées pour cette paire de capteurs. Déplacez-vous vers une autre zone nette de leur chevauchement.",
    "This sensor pair is verified. Move into the overlap with the next sensor until every sensor is connected.": "Cette paire de capteurs est vérifiée. Déplacez-vous dans le chevauchement avec le capteur suivant jusqu'à ce que tous les capteurs soient reliés.",
    "Restart test": "Recommencer le test",
    "Keep exactly one person visible to every positioning sensor, then capture again.": "Gardez exactement une personne visible par chaque capteur, puis capturez à nouveau.",
    "Additional presence is active without an X/Y position. No target is invented.": "Une présence supplémentaire est active sans position X/Y. Aucune cible n'est inventée.",
    "{count} positioned · presence": "{count} positionné(s) · présence",
    "{count} positioned": "{count} positionné(s)",
    "{count} source tracks visible; room count is still being verified.": "{count} pistes sources visibles ; le nombre dans la pièce est encore en cours de vérification.",
    "1 room track visible.": "1 piste de pièce visible.",
    "{count} room tracks visible.": "{count} pistes de pièce visibles.",
