    "The dashed preview follows the radar rays beyond the mirror. Increase the depth only when ghost targets appear farther behind it.": "La vista previa discontinua sigue los rayos del radar más allá del espejo. Aumenta la profundidad solo si los objetivos fantasma aparecen más lejos detrás.",
    "Each protected mirror uses one of the radar's two exclusion slots. Raw diagnostic target entities remain unchanged; the Floorplan Designer, the UltimateSensor room view and firmware people counting ignore the protected area.": "Cada espejo protegido usa uno de los dos espacios de exclusión del radar. Las entidades de diagnóstico sin procesar no cambian; el diseñador de planos, la vista de habitación de UltimateSensor y el recuento de personas del firmware ignoran el área protegida.",
