    "Raise a thermostat setpoint during the cheapest block to store comfort, then lower it during the price peak. Uses the home as thermal storage.": "Sube la temperatura deseada de un termostato durante el bloque más barato para almacenar calor y bájala durante el pico de precio. Usa la casa como almacenamiento térmico.",
    "Raise the limit, or immediately restart a paused inverter, when grid import exceeds this value.": "Aumenta el límite o reinicia de inmediato un inversor en pausa cuando la importación de la red supere este valor.",
