    "Remove both the SmartHomeShop link and ESPHome configuration. This does not erase the firmware or delete the node from the ESPHome dashboard.": "Elimina el enlace con SmartHomeShop y la configuración de ESPHome. Esto no borra el firmware ni elimina el nodo del panel de ESPHome.",
