    "Remove SmartHomeShop settings and derived entities. The ESPHome device and its original entities stay in Home Assistant.": "Elimina la configuración de SmartHomeShop y las entidades derivadas. El dispositivo ESPHome y sus entidades originales permanecen en Home Assistant.",
    "Remove the battery planner and its automation?": "¿Eliminar el planificador de batería y su automatización?",
    "Remove the SmartHomeShop link and hide this card. ESPHome, original entities, automations and recorder history stay unchanged. You can restore it later.": "Elimina la vinculación con SmartHomeShop y oculta esta tarjeta. ESPHome, las entidades originales, las automatizaciones y el historial no cambian. Podrás restaurar el dispositivo más adelante.",
