    "Use solar surplus for a device": "Usar el excedente solar para un dispositivo",
    "Use the lowest value accepted by the inverter. A small non-zero limit is safer for many models.": "Usa el valor más bajo que acepte el inversor. Un límite pequeño distinto de cero es más seguro para muchos modelos.",
    "Used for the smart-savings estimate and the fuse guard below.": "Se usa para la estimación de Smart Savings y la protección del fusible de abajo.",
