    'Commands use normal Home Assistant services. Smart EV waits for entity-state confirmation. A new start that cannot be confirmed is stopped and waits five minutes; adjustments to an already owned session can be retried once. A current controller that cannot accept 0 A requires a separate stop switch before Automatic mode can start it.': 'Opdrachten gebruiken normale Home Assistant-services. Slim laden wacht op bevestiging van de entiteitsstatus. Een nieuwe start zonder bevestiging wordt gestopt en wacht vijf minuten; aanpassingen aan een al beheerde sessie kunnen één keer opnieuw worden geprobeerd. Een stroomregelaar die geen 0 A accepteert heeft een aparte stopschakelaar nodig voordat de automatische stand hem mag starten.',
    'Commands use normal Home Assistant services. Smart EV waits for entity-state confirmation. A new start that cannot be confirmed is stopped and waits five minutes; a failed adjustment to an owned session is stopped safely before one fresh start attempt after another live safety check. A current controller that cannot accept 0 A requires a separate stop switch before Automatic mode can start it.': 'Opdrachten gebruiken normale Home Assistant-services. Slim laden wacht op bevestiging van de entiteitsstatus. Een nieuwe start zonder bevestiging wordt gestopt en wacht vijf minuten; een mislukte aanpassing van een beheerde sessie wordt eerst veilig gestopt vóór één nieuwe startpoging na een extra actuele veiligheidscontrole. Een stroomregelaar die geen 0 A accepteert heeft een aparte stopschakelaar nodig voordat de automatische stand hem mag starten.',
