    'Commands use normal Home Assistant services. Smart EV waits for entity-state confirmation. A new start that cannot be confirmed is stopped and waits five minutes; adjustments to an already owned session can be retried once. A current controller that cannot accept 0 A requires a separate stop switch before Automatic mode can start it.': 'Befehle nutzen normale Home-Assistant-Dienste. Smart EV wartet auf die Bestätigung des Entitätsstatus. Ein unbestätigter neuer Ladestart wird gestoppt und wartet fünf Minuten; Anpassungen einer bereits verwalteten Sitzung können einmal wiederholt werden. Ein Stromregler ohne 0-A-Unterstützung benötigt einen separaten Stoppschalter, bevor die Automatik ihn starten darf.',
    'Commands use normal Home Assistant services. Smart EV waits for entity-state confirmation. A new start that cannot be confirmed is stopped and waits five minutes; a failed adjustment to an owned session is stopped safely before one fresh start attempt after another live safety check. A current controller that cannot accept 0 A requires a separate stop switch before Automatic mode can start it.': 'Befehle nutzen normale Home-Assistant-Dienste. Smart EV wartet auf die Bestätigung des Entitätsstatus. Ein unbestätigter neuer Start wird gestoppt und wartet fünf Minuten; eine fehlgeschlagene Anpassung einer verwalteten Sitzung wird vor einem neuen Startversuch nach einer weiteren aktuellen Sicherheitsprüfung sicher gestoppt. Ein Stromregler ohne 0-A-Unterstützung benötigt einen separaten Stoppschalter, bevor die Automatik ihn starten darf.',
    'Automatic control waits for fresh P1 data, respects main-fuse headroom and verifies charger feedback. An unconfirmed new start is stopped instead of retried immediately. Missing or stale safety signals block charging instead of guessing.': 'Die Automatik wartet auf aktuelle P1-Daten, beachtet die Reserve der Hauptsicherung und prüft die Rückmeldung der Wallbox. Ein unbestätigter neuer Ladestart wird gestoppt statt sofort wiederholt. Fehlende oder veraltete Sicherheitssignale blockieren das Laden, anstatt Werte zu schätzen.',
