    'Commands use normal Home Assistant services. Smart EV waits for entity-state confirmation. A new start that cannot be confirmed is stopped and waits five minutes; a failed adjustment to an owned session is stopped safely before one fresh start attempt after another live safety check. A current controller that cannot accept 0 A requires a separate stop switch before Automatic mode can start it.': 'Les commandes utilisent les services Home Assistant. Smart EV attend la confirmation de l\'état de l\'entité. Un nouveau démarrage non confirmé est arrêté et attend cinq minutes ; l\'ajustement échoué d\'une session gérée est arrêté en sécurité avant une nouvelle tentative de démarrage après un nouveau contrôle de sécurité en direct. Un contrôleur qui n\'accepte pas 0 A nécessite un interrupteur d\'arrêt séparé avant que le mode automatique puisse le démarrer.',
