const SMART_LOAD_LANGUAGES = ['nl', 'de', 'fr', 'es'] as const;
for (const [index, language] of SMART_LOAD_LANGUAGES.entries()) {
  Object.assign(
    PANEL_TRANSLATIONS[language],
    Object.fromEntries(SMART_LOAD_TRANSLATION_ROWS.map(row => [row[0], row[index + 1]])),
    Object.fromEntries(ENERGY_CONTROL_TRANSLATION_ROWS.map(row => [row[0], row[index + 1]])),
  );
}

